const GLYPH: Record<string, string> = { aries: '♈', taurus: '♉', gemini: '♊', cancer: '♋', leo: '♌', virgo: '♍', libra: '♎', scorpio: '♏', sagittarius: '♐', capricorn: '♑', aquarius: '♒', pisces: '♓' };
const CARDS = ['the_fool', 'the_magician', 'the_high_priestess', 'the_lovers', 'the_star', 'the_moon'];
const BAT_SPRITE = "data:image/webp;base64,";
const BAT_PATHS = [
  [-0.40, -0.76, -28, 96, 4.6], [-0.18, -0.93, -12, 76, 4.3],
  [0.22, -0.88, 24, 92, 4.9], [0.78, -0.62, 38, 108, 5.1],
  [0.88, 0.18, 58, 86, 4.8], [0.36, 0.85, -22, 104, 5.0],
  [-0.22, 0.82, -42, 82, 4.7], [-0.55, 0.16, -60, 110, 4.5],
];
const HalloweenBats: React.FC = () => {
  const ref = React.useRef<HTMLDivElement>(null);
  const [active, setActive] = React.useState(false);
  const [geometry, setGeometry] = React.useState({ x: 0, y: 0, w: 0, h: 0 });
  React.useEffect(() => {
    const layer = ref.current;
    if (!layer) return;
    const section = layer.closest('.st-halloween')!;
    const art = section.querySelector<HTMLImageElement>('.sale-art img')!;
    const motion = window.matchMedia('(prefers-reduced-motion: reduce)');
    let disposed = false;
    let observer: IntersectionObserver | undefined;
    const measure = () => {
      const bounds = section.getBoundingClientRect();
      const image = art.getBoundingClientRect();
      const mobile = window.matchMedia('(max-width:760px)').matches;
      const scale = Math.max(image.width / 1100, image.height / 733);
      // The left eye is at (346, 393) in the original 1100 x 733 artwork.
      // Use the same object-cover offsets as the artwork at each breakpoint.
      setGeometry({ x: image.left - bounds.left + (image.width - 1100 * scale) * (mobile ? .4 : 0) + 346 * scale,
        y: image.top - bounds.top + (image.height - 733 * scale) * (mobile ? .5 : .64) + 393 * scale,
        w: bounds.width, h: bounds.height });
    };
    const resize = new ResizeObserver(measure);
    resize.observe(section); resize.observe(art); measure();
    const sprite = new Image(); sprite.src = BAT_SPRITE;
    Promise.all([art.decode().catch(() => {}), sprite.decode()]).then(() => {
      if (disposed || motion.matches) return;
      measure();
      observer = new IntersectionObserver(([entry]) => {
        if (entry.isIntersecting && !motion.matches) { setActive(true); observer?.disconnect(); }
      }, { threshold: .25 });
      observer.observe(section);
    }).catch(() => {});
    return () => { disposed = true; resize.disconnect(); observer?.disconnect(); };
  }, []);
  return <div ref={ref} className={`sale-bats${active ? ' is-active' : ''}`} aria-hidden="true">
    {BAT_PATHS.map(([dx, dy, bank, size, duration], i) => {
      const ex = dx * geometry.w * 1.35, ey = dy * geometry.h * 1.4;
      return <div key={i} className="sale-bat" style={{ left: geometry.x, top: geometry.y,
        '--ex': `${ex}px`, '--ey': `${ey}px`, '--mx': `${ex * .40}px`, '--my': `${ey * .40 - 26}px`,
        '--bank': `${bank}deg`, '--size': `${size}px`, '--duration': `${duration}s`,
        '--flap': `${.28 + i * .013}s`, '--phase': `${-i * .047}s`,
      } as React.CSSProperties}><span className="sale-bat-texture" style={{ backgroundImage: `url(${BAT_SPRITE})` }} /></div>;
    })}
  </div>;
};
